import React, { useEffect } from 'react'
import { Row, Col, Form, DatePicker, Button, Icon, Input, Select, Spin } from 'antd'
import { horizontalLayout } from '../../../../utils/formLayout'
import { useQuotationSummary } from '../../../../state/QuotationDataSummary/hooks/useQuotationDataSummary'
import { useLeadConfig } from '../../../../state/hooks'
import { RowWithMargin } from '../../../../CommonComponents'
import { useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import moment from 'moment-timezone'

const { RangePicker } = DatePicker
const { Item } = Form

const Filters = ({ form, onFilter, ...props }) => {
  const { getFieldDecorator, setFieldsValue } = form
  const { leadConfigData, leadConfigRequest } = useLeadConfig()
  const { quotationSummaryRequest } = useQuotationSummary()
  const [{ QUOTATION_SUMMARY_LOADER }] = useLoaderContextValue()

  const handleResetFilter = () => {
    onFilter()
    form.resetFields()
    quotationSummaryRequest()
    window.sessionStorage.removeItem('eb-quotation-data-summary-filters')
    window.sessionStorage.removeItem('eb-quotation-data-summary-filters-to-be-sent')
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    form.validateFields((err, values) => {
      if (!err) {
        const { created_at: createdAtRange, updated_at: updatedAtRange, ...toBeSentValues } = values
        window.sessionStorage.setItem('eb-quotation-data-summary-filters', JSON.stringify({
          ...toBeSentValues,
          created_at: Array.isArray(createdAtRange) ? createdAtRange.map(date => date.format('YYYY-MM-DD')) : undefined,
          updated_at: Array.isArray(updatedAtRange) ? updatedAtRange.map(date => date.format('YYYY-MM-DD')) : undefined
        }))
        toBeSentValues.created_at_start_date = Array.isArray(createdAtRange) ? createdAtRange[0]?.format('YYYY-MM-DD') : undefined
        toBeSentValues.created_at_end_date = Array.isArray(createdAtRange) ? createdAtRange[1]?.format('YYYY-MM-DD') : undefined
        toBeSentValues.updated_at_start_date = Array.isArray(updatedAtRange) ? updatedAtRange[0]?.format('YYYY-MM-DD') : undefined
        toBeSentValues.updated_at_end_date = Array.isArray(updatedAtRange) ? updatedAtRange[1]?.format('YYYY-MM-DD') : undefined
        quotationSummaryRequest(toBeSentValues)
        onFilter(toBeSentValues)
        window.sessionStorage.setItem('eb-quotation-data-summary-filters-to-be-sent', JSON.stringify(toBeSentValues))
      }
    })
  }

  useEffect(() => {
    leadConfigRequest()
  }, [leadConfigRequest])

  useEffect(() => {
    const sessionFilters = window.sessionStorage.getItem('eb-quotation-data-summary-filters')
    try {
      if (sessionFilters) {
        const { created_at: createdAt, updated_at: updatedAt, ...filters } = JSON.parse(sessionFilters)
        setFieldsValue({
          updated_at: Array.isArray(updatedAt) ? updatedAt.map(date => moment(date)) : undefined,
          created_at: Array.isArray(createdAt) ? createdAt.map(date => moment(date)) : undefined,
          ...filters
        })
      }
    } catch (e) {
      console.error(e)
    }
  }, [setFieldsValue])

  return (
    <Spin spinning={!!QUOTATION_SUMMARY_LOADER}>
      <RowWithMargin>
        <Form
          onSubmit={handleSubmit}
          {...horizontalLayout}
          labelCol={{ xs: 24, sm: 6 }}
        >
          <Row gutter={16}>
            <Col span={8}>
              <h3>Filters</h3>
            </Col>
            <Col offset={12} span={4}>
              <Item>
                <Button
                  type='danger'
                  onClick={handleResetFilter}
                >
                  Clear Filters <Icon type='delete' />
                </Button>
              </Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={10}>
              <Item label='Case ID' labelAlign='left'>
                {
                getFieldDecorator('case_id', {})(
                  <Input placeholder='1' allowClear />
                )
              }
              </Item>
            </Col>
            <Col span={10}>
              <Item label='Company' labelAlign='left'>
                {
                getFieldDecorator('company_name', {
                  rules: [
                    {
                      max: 128,
                      message: 'Company name should not be greater than 128 characters'
                    }
                  ]
                })(
                  <Input placeholder='PT VUTEQ INDONESIA' allowClear />
                )
              }
              </Item>
            </Col>

          </Row>

          <Row gutter={16}>
            <Col span={10}>
              <Item label='Created At' labelAlign='left'>
                {
                  getFieldDecorator('created_at', {})(
                    <RangePicker allowClear />
                  )
                }
              </Item>
            </Col>
            <Col span={10}>
              <Item label='Status' labelAlign='left'>
                {
                getFieldDecorator('case_status', {})(
                  <Select allowClear>
                    {leadConfigData && leadConfigData.case_status && leadConfigData.case_status.map(({ code, name }) => (
                      <Select.Option key={code} value={code}>{name}</Select.Option>
                    ))}
                  </Select>
                )
              }
              </Item>
            </Col>
          </Row>
          <Row gutter={16}>
            <Col span={10}>
              <Item label='Marketing' labelAlign='left'>
                {
                getFieldDecorator('marketing', {
                  rules: [
                    {
                      max: 128,
                      message: 'Marketing name should not be greater than 128 characters'
                    }
                  ]
                })(
                  <Input placeholder='Pingkan' allowClear />
                )
              }
              </Item>
            </Col>

            <Col span={10}>
              <Item label='Updated At' labelAlign='left'>
                {
                getFieldDecorator('updated_at', {})(
                  <RangePicker allowClear />
                )
              }
              </Item>
            </Col>
            <Col span={4}>
              <Item>
                <Button type='primary' htmlType='submit'>Apply Filters <Icon type='filter' /></Button>
              </Item>
            </Col>
          </Row>
          <Row>
            <Col span={7} />
            <Col span={7} />
          </Row>
        </Form>
      </RowWithMargin>
    </Spin>
  )
}
export default Form.create({ name: 'insurer-filter' })(Filters)
