import { useLoaderContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { Button, Empty, Icon, Modal, Spin, Typography } from 'antd'
import moment from 'moment'
import { useCallback, useEffect, useState } from 'react'
import { useCaseQuotationRemarks, useLeadConfig, useResetState } from '../../state/hooks'
import { RemarksContainer, RemarkWrapper } from './index.style'

const { Text } = Typography

const CaseQuotatoinRemarks = ({ url, id }) => {
  const { getRemarks, caseQuotationRemarksData } = useCaseQuotationRemarks()
  const [visible, setVisible] = useState(false)
  // const [{ CASE_QUOTATION_REMARKS_ERROR, caseQuotationRemarksStatus }] = useErrorContextValue()
  const { leadConfigData, leadConfigRequest } = useLeadConfig()
  const [{ CASE_QUOTATION_REMARKS_LOADER }] = useLoaderContextValue()
  const { resetState } = useResetState()
  const { resetError } = useResetError()
  const closeModal = useCallback(() => setVisible(false), [])
  useEffect(() => {
    if (visible) {
      getRemarks({ url, id })
    }
  }, [getRemarks, url, id, visible])
  useEffect(() => {
    return () => {
      if (visible) {
        resetError(['caseQuotationRemarksStatus', 'CASE_QUOTATION_REMARKS_ERROR'])
        resetState(['caseQuotationRemarksData'])
      }
    }
  }, [visible, resetError, resetState])
  useEffect(() => {
    leadConfigRequest()
  }, [leadConfigRequest])
  return (
    <RemarksContainer>
      <Button
        type='link'
        onClick={() => setVisible(true)}
      >
        View <Icon type='eye' />
      </Button>
      <Modal
        visible={visible}
        onOk={closeModal}
        onCancel={closeModal}
        title='Remarks'
      >
        <Spin spinning={!!CASE_QUOTATION_REMARKS_LOADER}>
          {
            caseQuotationRemarksData?.data?.map(({ type, action, updated_by: updatedBy, status_updated_at: statusUpdatedAt, updated_status: updatedStatus, group }, index) => (
              <RemarkWrapper key={index}>
                <Text strong>
                  {type} - {action} - by {updatedBy} - {group} - {moment(statusUpdatedAt).format('DD/MM/yyyy')}
                </Text>
                <div>
                  <Text strong>Updated Status - [{leadConfigData && leadConfigData[type === 'Case' ? 'case_status' : 'quotation_status']?.find(({ code: statusCode }) => statusCode === updatedStatus)?.name}]</Text>
                </div>
              </RemarkWrapper>
            )) || <Empty />
          }
        </Spin>
      </Modal>
    </RemarksContainer>
  )
}
export default CaseQuotatoinRemarks
