import ebUrls from '../../../../../request/urls/employeeBenefit'

const actions = {

  QUOTATION_SUMMARY_REQUEST: 'QUOTATION_SUMMARY_REQUEST',
  QUOTATION_SUMMARY: 'QUOTATION_SUMMARY',
  EXPORT_EXCEL_REQUEST: 'EXPORT_EXCEL_REQUEST',
  EXPORT_EXCEL: 'EXPORT_EXCEL',

  getQuotationSummary: (payload) => ({
    type: actions.QUOTATION_SUMMARY_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.getQuotationSummary
    }
  }),
  exportExcel: (payload) => ({
    type: actions.EXPORT_EXCEL_REQUEST,
    payload: {
      ...payload,
      method: 'get',
      url: ebUrls.exportExcel
    }
  })
}

export default actions
