import { Button, Col, Icon, Row } from 'antd'
import moment from 'moment'
import { formatIntl, formatIntlCurrency } from '../../../../../../helpers/utility'
import ebUrls from '../../../../../../request/urls/employeeBenefit'
import ButtonWithPermission from '../../../components/ButtonWithPermission'
import CaseQuotatoinRemarks from '../../../components/CaseQuotationRemarks'
import { mapCodeToNameFromLeadConfigData } from '../../../utils/helpers'
import ViewDocumentsModal from './components/ViewDocumentsModal/inex'

export const quotationSummaryColumns = ({ editCase, addQuotation, goToQuotationDetail, downloadRequest, leadConfigData }) => [
  {
    title: 'Actions',
    width: 250,
    key: 'actions',
    render: (rowData) => (
      <Row className='mb-5'>
        <Col span={11}>
          <ButtonWithPermission
            type='primary'
            onClick={() => editCase(rowData)}
            requiredPermission='ops.eb_update_case'
          >
            <Icon type='edit' /> Case
          </ButtonWithPermission>
        </Col>
        <Col span={13}>
          <ButtonWithPermission
            type='primary'
            className='ant-btn ant-btn-primary'
            ghost
            onClick={() => addQuotation({ case_id: rowData.id })}
            requiredPermission='ops.eb_create_quotation'
            disabled={['CLOSING', 'LOSING'].includes(rowData?.case_status)}
          >
            <Icon type='plus' /> Quotation
          </ButtonWithPermission>
        </Col>
      </Row>
    )
  },
  {
    title: 'ID',
    dataIndex: 'id',
    width: 100
  },
  {
    title: 'Quotation Count',
    dataIndex: 'quotation_count',
    render: (count = 0, rowData) => (
      <>
        {count} |
        <Button
          disabled={!count} type='link'
          onClick={() => goToQuotationDetail(rowData)}
        >
          View Details <Icon type='eye' />
        </Button>
      </>
    ),
    width: 190
  },
  {
    title: 'Case Status',
    dataIndex: 'case_status',
    width: 200,
    render: caseStatus => mapCodeToNameFromLeadConfigData(caseStatus, 'case_status', leadConfigData)
  },
  {
    title: 'Company Name',
    dataIndex: 'company_name',
    width: 200
  },
  {
    title: 'Line of Business',
    dataIndex: 'business_type',
    width: 200
  },
  {
    title: 'Agent/Ref',
    dataIndex: 'agent',
    width: 200
  },
  {
    title: 'Marketing',
    dataIndex: 'marketing_name',
    width: 200
  },
  {
    title: 'PIC',
    dataIndex: 'pic_name',
    width: 200
  },
  {
    title: 'PIC Phone Number',
    dataIndex: 'pic_phone',
    width: 200
  },
  {
    title: 'PIC Email',
    dataIndex: 'pic_email',
    width: 200
  },
  {
    title: 'Channel',
    dataIndex: 'channel',
    width: 200,
    render: channel => mapCodeToNameFromLeadConfigData(channel, 'channels', leadConfigData)
  },
  {
    title: 'Product',
    dataIndex: 'product',
    width: 200,
    render: product => Array.isArray(product) && product.map((item, index, array) => index !== array.length - 1 ? `${mapCodeToNameFromLeadConfigData(item, 'products', leadConfigData)}, ` : mapCodeToNameFromLeadConfigData(item, 'products', leadConfigData))
  },
  {
    title: 'Total Participant',
    dataIndex: 'participant_count',
    width: 200,
    render: participantCount => formatIntl(participantCount)
  },
  {
    title: 'Budget (Rp)',
    dataIndex: 'budget',
    width: 200,
    render: (budget) => formatIntl(budget)
  },
  {
    title: 'Sub Office',
    dataIndex: 'sub_offices',
    render: subOffices => Array.isArray(subOffices) && subOffices.length,
    width: 80
  },
  {
    title: 'Existing Insurance',
    dataIndex: 'existing_insurance_provider',
    width: 120
  },
  {
    title: 'Existing Broker',
    dataIndex: 'existing_broker',
    width: 120
  },
  {
    title: 'Agent Commission',
    dataIndex: 'agent_commission',
    width: 100,
    render: agentCommision => formatIntl(agentCommision)
  },
  {
    title: 'Paspol Commission',
    dataIndex: 'paspol_commission',
    width: 100,
    render: paspolCommision => formatIntl(paspolCommision)
  },
  {
    title: 'Add On Fee',
    dataIndex: 'add_on_fee',
    width: 200,
    render: (addOnFee) => formatIntlCurrency(addOnFee)
  },
  {
    title: 'Effective Date',
    dataIndex: 'effective_date',
    width: 120,
    render: effectiveDate => effectiveDate && moment(effectiveDate).format('DD MMM, YYYY')
  },
  {
    title: 'End Date',
    dataIndex: 'end_date',
    width: 120,
    render: endDate => endDate && moment(endDate).format('DD MMM, YYYY')
  },
  {
    title: 'Document Received',
    dataIndex: 'documents',
    render: (documents) => <ViewDocumentsModal documents={documents} downloadRequest={downloadRequest} />,
    width: 240
  },
  {
    title: 'Spak Document',
    dataIndex: 'spak_document',
    render: (file) => (
      <Button
        type='link'
        disabled={!file}
        onClick={() => {
          const fileName = file && file.split(':')[2]
          downloadRequest({
            action_type: 'GET',
            identifier: 'case',
            file_name: fileName
          })
        }}
      >
        View <Icon type='eye' />
      </Button>
    )
  },
  {
    title: 'Status Updated At',
    dataIndex: 'case_status_updated_date',
    width: 120,
    render: statusUpdatedAtDate => statusUpdatedAtDate && moment(statusUpdatedAtDate).format('DD MMM, YYYY')
  },
  {
    title: 'Remarks',
    widht: 200,
    render: ({ id }) => <CaseQuotatoinRemarks url={ebUrls.caseRemarks} id={id} />
  }
]
