import { useErrorContextValue, useLoaderContextValue } from '@pasarpolis/common-react-hooks'
import { Col, Row, Icon, Button, Table, Spin, Alert } from 'antd'
import { useEffect, useState } from 'react'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
import { downloadDataFromUrl } from '../../../../../../helpers/utility'
import { EbSectionWrapper } from '../../../CommonComponents'
import { ColTextAlignRight, RowWithMargin } from '../../../CommonComponents/index.style'
import ButtonWithPermission from '../../../components/ButtonWithPermission'
import { useDownloadFileFromGcs, useLeadConfig } from '../../../state/hooks'
import { useExportExcel, useQuotationSummary } from '../../../state/QuotationDataSummary/hooks/useQuotationDataSummary'
import Filters from './components/filters'
import { quotationSummaryColumns } from './utility'

const QuotationDataSummary = ({ history }) => {
  const { quotationSummaryData, quotationSummaryRequest } = useQuotationSummary()
  const { downloadRequest } = useDownloadFileFromGcs()
  const { exportExcelData, exportExcelRequest } = useExportExcel()
  const [{ QUOTATION_SUMMARY_LOADER, EXPORT_EXCEL_LOADER, DOWNLOAD_FILE_FROM_GCS_LOADER }] = useLoaderContextValue()
  const { leadConfigRequest, leadConfigData } = useLeadConfig()
  const [{ EXPORT_EXCEL_ERROR, exportExcelStatus, QUOTATION_SUMMARY_ERROR, quotationSummaryStatus }] = useErrorContextValue()
  const [listMetaData, setListMetaData] = useState({})
  const [filters, setFilters] = useState()

  const editCase = caseData => history.push({
    pathname: `/employee-benefits/edit-case/${caseData.id}`
  })
  const addQuotation = quotationData => history.push({
    pathname: '/employee-benefits/add-quotation',
    state: quotationData
  })

  const goToQuotationDetail = quotationData => history.push(`/employee-benefits/quotation-data-summary/${quotationData.id}`)

  const handleExportExcel = () => {
    exportExcelRequest({ ...filters })
  }

  useEffect(() => {
    if (exportExcelStatus === 'success' && exportExcelData && exportExcelData.url) {
      downloadDataFromUrl(exportExcelData.url)
    }
  }, [exportExcelData, exportExcelStatus])

  const handleTableChange = (params) => {
    const query = {
      page: params.current,
      per_page: params.pageSize
    }
    quotationSummaryRequest({ ...query, ...filters })
  }

  useEffect(() => {
    if (quotationSummaryData && quotationSummaryData.meta_data) {
      setListMetaData(quotationSummaryData.meta_data)
    }
  }, [quotationSummaryData])

  useEffect(() => {
    let appliedFiltersInSessionStorage
    let appliedFilters
    try {
      appliedFiltersInSessionStorage = window.sessionStorage.getItem('eb-quotation-data-summary-filters-to-be-sent')
      if (appliedFiltersInSessionStorage) {
        appliedFilters = JSON.parse(appliedFiltersInSessionStorage)
      }
    } catch (e) {
      console.error(e)
    }
    quotationSummaryRequest(appliedFilters)
    setFilters(appliedFilters)
    leadConfigRequest()
  }, [leadConfigRequest, quotationSummaryRequest, setFilters])

  return (
    <>
      <EbSectionWrapper>
        {QUOTATION_SUMMARY_ERROR && <Alert type='error' message={quotationSummaryStatus} banner />}
        {EXPORT_EXCEL_ERROR && <Alert type='error' message={exportExcelStatus} banner />}
        <Row gutter={16} className='mb-5'>
          <Col span={8}><h2>Quotation Data Summary</h2></Col>
          <ColTextAlignRight span={8}>
            <ButtonWithPermission
              type='primary'
              onClick={() => history.push('/employee-benefits/add-new-case')}
              requiredPermission='ops.eb_create_case'
            >
              Add New Case <Icon type='plus' />
            </ButtonWithPermission>
          </ColTextAlignRight>
          <ColTextAlignRight span={8}>
            <ButtonWithPermission
              type='primary'
              onClick={() => history.push('/employee-benefits/add-quotation')}
              requiredPermission='ops.eb_create_quotation'
            >
              Add Quotation For Existing Case <Icon type='plus' />
            </ButtonWithPermission>
          </ColTextAlignRight>
        </Row>
        <Filters onFilter={setFilters} />
      </EbSectionWrapper>
      <EbSectionWrapper>
        <Row gutter={16}>
          <ColTextAlignRight>
            <PermissionCheckerV2 requiredPermission='ops.eb_view_case_summary_data'>
              <Button
                type='primary'
                onClick={handleExportExcel}
                loading={!!EXPORT_EXCEL_LOADER}
              >
                Export to Excel <Icon type='file-excel' />
              </Button>
            </PermissionCheckerV2>
          </ColTextAlignRight>
        </Row>
        <Spin spinning={!!QUOTATION_SUMMARY_LOADER || !!DOWNLOAD_FILE_FROM_GCS_LOADER}>
          <RowWithMargin gutter={16}>
            <Col span={24}>
              <Table
                rowKey={({ quotation_id: quotationId, id: caseId }) => quotationId || `case-${caseId}`}
                columns={quotationSummaryColumns({ editCase, addQuotation, goToQuotationDetail, downloadRequest, leadConfigData })}
                dataSource={quotationSummaryData ? quotationSummaryData.data : []}
                bordered
                onChange={handleTableChange}
                pagination={{
                  pageSize: listMetaData.page_size,
                  total: listMetaData.total_records,
                  current: listMetaData.page
                }}
                scroll={{ x: true }}
              />
            </Col>
          </RowWithMargin>
        </Spin>
      </EbSectionWrapper>
    </>
  )
}
export default QuotationDataSummary
